#include <stdio.h>
int main(void) {
  int c = getchar();
  if (c >= '0' && c <= '9') printf("digit");
  else if (c >= 'a' && c <= 'z') printf("lower case");
  else if (c >= 'A' && c <= 'Z') printf("upper case");
  else printf("special character");
  return 0;
} (ctype.h isdigit/islower/isupper equivalent accepted.)
